dataSet.query:
ВЫБРАТЬ РАЗРЕШЕННЫЕ УсловияСделокРЕПО.СделкаРЕПО КАК СделкаРЕПО, УсловияСделокРЕПО.СделкаРЕПО.Контрагент КАК Контрагент, УсловияСделокРЕПО.ЦеннаяБумага.Эмитент.ЮрФизЛицо КАК Эмитент, УсловияСделокРЕПО.ЧастьСделкиРЕПО КАК ЧастьСделкиРЕПО, УсловияСделокРЕПО.Рынок КАК Рынок, УсловияСделокРЕПО.ЦеннаяБумага КАК ЦеннаяБумага ПОМЕСТИТЬ РеквизитыСделок ИЗ РегистрСведений.УсловияСделокРЕПО.СрезПоследних( &КонецПериода, Организация = &Организация И СделкаРЕПО.ВалютаСделки = &ВалютаРубли И СделкаРЕПО.МестоХранения <> ЗНАЧЕНИЕ(Справочник.МестаХранения.ВнебиржевойРынок)) КАК УсловияСделокРЕПО ГДЕ ВЫБОР КОГДА УсловияСделокРЕПО.ЧастьСделкиРЕПО = 2 ТОГДА УсловияСделокРЕПО.ДатаВторойЧастиРЕПО МЕЖДУ &НачалоПериода И &КонецПериода ИНАЧЕ УсловияСделокРЕПО.СделкаРЕПО.Дата МЕЖДУ &НачалоПериода И &КонецПериода КОНЕЦ И УсловияСделокРЕПО.Отменено = ЛОЖЬ И УсловияСделокРЕПО.ДатаОплаты = УсловияСделокРЕПО.ДатаПоставки {ГДЕ (УсловияСделокРЕПО.СчетДоверительногоУправления = &СчетДоверительногоУправления)}
ИНДЕКСИРОВАТЬ ПО УсловияСделокРЕПО.СделкаРЕПО ;
//////////////////////////////////////////////////////////////////////////////// ВЫБРАТЬ РАЗРЕШЕННЫЕ РАЗЛИЧНЫЕ РеквизитыСделок.Контрагент КАК Контрагент ПОМЕСТИТЬ КонтрагентыСделок ИЗ РеквизитыСделок КАК РеквизитыСделок ГДЕ РеквизитыСделок.Контрагент <> ЗНАЧЕНИЕ(Справочник.ЮрФизЛица.ПустаяСсылка) ;
//////////////////////////////////////////////////////////////////////////////// ВЫБРАТЬ РАЗРЕШЕННЫЕ РАЗЛИЧНЫЕ РеквизитыСделок.Эмитент КАК Эмитент ПОМЕСТИТЬ ЭмитентыСделок ИЗ РеквизитыСделок КАК РеквизитыСделок ГДЕ РеквизитыСделок.Эмитент <> ЗНАЧЕНИЕ(Справочник.ЮрФизЛица.ПустаяСсылка) ;
//////////////////////////////////////////////////////////////////////////////// ВЫБРАТЬ РАЗРЕШЕННЫЕ РАЗЛИЧНЫЕ РеквизитыСделок.ЦеннаяБумага КАК ЦеннаяБумага ПОМЕСТИТЬ ЦенныеБумагиСделок ИЗ РеквизитыСделок КАК РеквизитыСделок ;
//////////////////////////////////////////////////////////////////////////////// ВЫБРАТЬ РАЗРЕШЕННЫЕ РАЗРЕШЕННЫЕ УсловияСделокРЕПО.СделкаРЕПО КАК СделкаРЕПО ПОМЕСТИТЬ НеобработанныеСделки ИЗ РегистрСведений.УсловияСделокРЕПО.СрезПоследних( &КонецПериода, Организация = &Организация И (СделкаРЕПО.ВалютаСделки <> &ВалютаРубли ИЛИ СделкаРЕПО.МестоХранения = ЗНАЧЕНИЕ(Справочник.МестаХранения.ВнебиржевойРынок))) КАК УсловияСделокРЕПО ГДЕ ВЫБОР КОГДА УсловияСделокРЕПО.ЧастьСделкиРЕПО = 2 ТОГДА УсловияСделокРЕПО.ДатаВторойЧастиРЕПО МЕЖДУ &НачалоПериода И &КонецПериода ИНАЧЕ УсловияСделокРЕПО.СделкаРЕПО.Дата МЕЖДУ &НачалоПериода И &КонецПериода КОНЕЦ И УсловияСделокРЕПО.Отменено = ЛОЖЬ И УсловияСделокРЕПО.ДатаОплаты = УсловияСделокРЕПО.ДатаПоставки {ГДЕ (УсловияСделокРЕПО.СчетДоверительногоУправления = &СчетДоверительногоУправления)}
ОБЪЕДИНИТЬ
ВЫБРАТЬ УсловияСделокРЕПО.СделкаРЕПО ИЗ РегистрСведений.УсловияСделокРЕПО.СрезПоследних( &КонецПериода, Организация = &Организация И СделкаРЕПО.ВалютаСделки = &ВалютаРубли И СделкаРЕПО.МестоХранения <> ЗНАЧЕНИЕ(Справочник.МестаХранения.ВнебиржевойРынок)) КАК УсловияСделокРЕПО ГДЕ ВЫБОР КОГДА УсловияСделокРЕПО.ЧастьСделкиРЕПО = 2 ТОГДА УсловияСделокРЕПО.ДатаВторойЧастиРЕПО МЕЖДУ &НачалоПериода И &КонецПериода ИНАЧЕ УсловияСделокРЕПО.СделкаРЕПО.Дата МЕЖДУ &НачалоПериода И &КонецПериода КОНЕЦ И УсловияСделокРЕПО.Отменено = ЛОЖЬ И УсловияСделокРЕПО.ДатаОплаты <> УсловияСделокРЕПО.ДатаПоставки {ГДЕ (УсловияСделокРЕПО.СчетДоверительногоУправления = &СчетДоверительногоУправления)}
ОБЪЕДИНИТЬ
ВЫБРАТЬ УсловияСделокРЕПО.СделкаРЕПО ИЗ РегистрСведений.УсловияСделокРЕПО.СрезПоследних( &КонецПериода, Организация = &Организация И СделкаРЕПО.ВалютаСделки = &ВалютаРубли И СделкаРЕПО.МестоХранения <> ЗНАЧЕНИЕ(Справочник.МестаХранения.ВнебиржевойРынок)) КАК УсловияСделокРЕПО ЛЕВОЕ СОЕДИНЕНИЕ РегистрНакопления.РасходыПоСделке.Обороты( &НачалоПериода, &КонецПериода, , Организация = &Организация И ВидЗадолженности = ЗНАЧЕНИЕ(Справочник.ВидыЗадолженности.ПоТорговойКомиссии) И Сделка В (ВЫБРАТЬ РеквизитыСделок.СделкаРЕПО ИЗ РеквизитыСделок)) КАК ТорговаяКомиссияСделки ПО (ТорговаяКомиссияСделки.Сделка = УсловияСделокРЕПО.СделкаРЕПО) И (УсловияСделокРЕПО.ЧастьСделкиРЕПО = 1) ЛЕВОЕ СОЕДИНЕНИЕ РегистрНакопления.РасходыПоСделке.Обороты( &НачалоПериода, &КонецПериода, , Организация = &Организация И ВидЗадолженности = ЗНАЧЕНИЕ(Справочник.ВидыЗадолженности.ПоБрокерскойКомиссии) И Сделка В (ВЫБРАТЬ РеквизитыСделок.СделкаРЕПО ИЗ РеквизитыСделок)) КАК БрокерскаяКомиссияСделки ПО (БрокерскаяКомиссияСделки.Сделка = УсловияСделокРЕПО.СделкаРЕПО) И (УсловияСделокРЕПО.ЧастьСделкиРЕПО = 1) ГДЕ ВЫБОР КОГДА УсловияСделокРЕПО.ЧастьСделкиРЕПО = 2 ТОГДА УсловияСделокРЕПО.ДатаВторойЧастиРЕПО МЕЖДУ &НачалоПериода И &КонецПериода ИНАЧЕ УсловияСделокРЕПО.СделкаРЕПО.Дата МЕЖДУ &НачалоПериода И &КонецПериода КОНЕЦ И УсловияСделокРЕПО.Отменено = ЛОЖЬ И УсловияСделокРЕПО.ДатаОплаты = УсловияСделокРЕПО.ДатаПоставки И (ЕСТЬNULL(ТорговаяКомиссияСделки.Валюта, &ВалютаРубли) <> &ВалютаРубли ИЛИ ЕСТЬNULL(БрокерскаяКомиссияСделки.Валюта, &ВалютаРубли) <> &ВалютаРубли) {ГДЕ (УсловияСделокРЕПО.СчетДоверительногоУправления = &СчетДоверительногоУправления)} ;
//////////////////////////////////////////////////////////////////////////////// ВЫБРАТЬ РАЗРЕШЕННЫЕ ЛОЖЬ КАК Необработано, УсловияСделокРЕПО.СделкаРЕПО КАК СделкаРЕПО, ВЫБОР КОГДА СделкиРЕПО.СделкаСЦентральнымКонтрагентом ТОГДА "РЕПО с ЦК" ИНАЧЕ "РЕПО" КОНЕЦ КАК РежимТоргов, СделкиРЕПО.МестоХранения.Биржа КАК МестоЗаключенияСделки, ВЫБОР КОГДА СделкиРЕПО.СделкаСЦентральнымКонтрагентом ТОГДА "Центральный контрагент" ИНАЧЕ ЕСТЬNULL(РеквизитыКонтрагента.ПолноеНаименованиеПоУставу, СделкиРЕПО.КонтрагентНаБирже) КОНЕЦ КАК ПолноеНаименованиеКонтрагента, ВЫБОР КОГДА СделкиРЕПО.СделкаСЦентральнымКонтрагентом ТОГДА "" ИНАЧЕ ЕСТЬNULL(РеквизитыКонтрагента.ИНН, "") КОНЕЦ КАК ИННКонтрагента, ВЫБОР КОГДА СделкиРЕПО.СделкаСЦентральнымКонтрагентом И СделкиРЕПО.НомерСделкиСЦентральнымКонтрагентом <> "" ТОГДА СделкиРЕПО.НомерСделкиСЦентральнымКонтрагентом ИНАЧЕ ЕСТЬNULL(СделкиРЕПО.ПерваяЧастьРЕПО.НомерСделки, СделкиРЕПО.НомерСделки) КОНЕЦ КАК УИДСделки, ВЫБОР КОГДА СделкиРЕПО.ВидСделки = ЗНАЧЕНИЕ(Перечисление.ВидыСделок.Продажа) ТОГДА "Прямое РЕПО" ИНАЧЕ "Обратное РЕПО" КОНЕЦ КАК ТипСделки, УсловияСделокРЕПО.ЧастьСделкиРЕПО КАК ЧастьСделки, ВЫБОР КОГДА УсловияСделокРЕПО.ЧастьСделкиРЕПО = 1 ТОГДА "Открыта" ИНАЧЕ "Закрыта" КОНЕЦ КАК СтатусСделки, ВЫБОР КОГДА УсловияСделокРЕПО.ЧастьСделкиРЕПО = 2 ТОГДА УсловияСделокРЕПО.ДатаВторойЧастиРЕПО ИНАЧЕ УсловияСделокРЕПО.СделкаРЕПО.Дата КОНЕЦ КАК ВремяСовершенияСделки, УсловияСделокРЕПО.ДатаИсполнения КАК ВремяРасчетов, УсловияСделокРЕПО.Рынок КАК ТипЦеннойБумаги, КодыISINЦенныхБумаг.Код КАК ISIN, УсловияСделокРЕПО.ЦеннаяБумага.ГосударственныйРегистрационныйНомер КАК НомерГосРегистрации, РеквизитыЭмитента.ПолноеНаименованиеПоУставу КАК ПолноеНаименованиеЭмитента, ЕСТЬNULL(РеквизитыЭмитента.ИНН, "") КАК ИННЭмитента, УсловияСделокРЕПО.Количество КАК Количество, УсловияСделокРЕПО.Сумма + УсловияСделокРЕПО.СуммаКупона КАК СуммаСделкиРуб, УсловияСделокРЕПО.СуммаКупона КАК СуммаНКДРуб, РАЗНОСТЬДАТ(СделкиРЕПО.Дата, УсловияСделокРЕПО.ДатаВторойЧастиРЕПО, ДЕНЬ) + 1 КАК СрокРЕПО, СделкиРЕПО.СтавкаРЕПО КАК Ставка, ЕСТЬNULL(ТорговаяКомиссияСделки.СуммаОборот, 0) КАК КомиссияОрганизатораТорговлиРуб, ЕСТЬNULL(БрокерскаяКомиссияСделки.СуммаОборот, 0) КАК КомиссияБрокераРуб ИЗ РегистрСведений.УсловияСделокРЕПО.СрезПоследних(&КонецПериода, Организация = &Организация) КАК УсловияСделокРЕПО ЛЕВОЕ СОЕДИНЕНИЕ Документ.СделкаРЕПО КАК СделкиРЕПО ПО (СделкиРЕПО.Ссылка = УсловияСделокРЕПО.СделкаРЕПО) ВНУТРЕННЕЕ СОЕДИНЕНИЕ РеквизитыСделок КАК РеквизитыСделок ПО (РеквизитыСделок.СделкаРЕПО = УсловияСделокРЕПО.СделкаРЕПО) И (РеквизитыСделок.ЧастьСделкиРЕПО = УсловияСделокРЕПО.ЧастьСделкиРЕПО) И (РеквизитыСделок.Рынок = УсловияСделокРЕПО.Рынок) И (РеквизитыСделок.ЦеннаяБумага = УсловияСделокРЕПО.ЦеннаяБумага) ЛЕВОЕ СОЕДИНЕНИЕ РегистрСведений.РеквизитыЮридическихЛиц.СрезПоследних( &КонецПериода, Язык = ЗНАЧЕНИЕ(Справочник.Языки.Русский) И Подразделение = ЗНАЧЕНИЕ(Справочник.Подразделения.ГруппаКомпаний) И ЮрФизЛицо В (ВЫБРАТЬ КонтрагентыСделок.Контрагент ИЗ КонтрагентыСделок)) КАК РеквизитыКонтрагента ПО (РеквизитыКонтрагента.ЮрФизЛицо = СделкиРЕПО.Контрагент) ЛЕВОЕ СОЕДИНЕНИЕ РегистрСведений.РеквизитыЮридическихЛиц.СрезПоследних( &КонецПериода, Язык = ЗНАЧЕНИЕ(Справочник.Языки.Русский) И Подразделение = ЗНАЧЕНИЕ(Справочник.Подразделения.ГруппаКомпаний) И ЮрФизЛицо В (ВЫБРАТЬ ЭмитентыСделок.Эмитент ИЗ ЭмитентыСделок)) КАК РеквизитыЭмитента ПО (РеквизитыЭмитента.ЮрФизЛицо = РеквизитыСделок.Эмитент) ЛЕВОЕ СОЕДИНЕНИЕ РегистрСведений.КодыВТорговыхСистемах.СрезПоследних( &КонецПериода, ВидКода = ЗНАЧЕНИЕ(Перечисление.ВидыКодовВТорговыхСистемах.ISIN) И Объект В (ВЫБРАТЬ ЦенныеБумагиСделок.ЦеннаяБумага ИЗ ЦенныеБумагиСделок)) КАК КодыISINЦенныхБумаг ПО (КодыISINЦенныхБумаг.Объект = УсловияСделокРЕПО.ЦеннаяБумага) ЛЕВОЕ СОЕДИНЕНИЕ РегистрНакопления.РасходыПоСделке.Обороты( &НачалоПериода, &КонецПериода, , Организация = &Организация И ВидЗадолженности = ЗНАЧЕНИЕ(Справочник.ВидыЗадолженности.ПоТорговойКомиссии) И Сделка В (ВЫБРАТЬ РеквизитыСделок.СделкаРЕПО ИЗ РеквизитыСделок)) КАК ТорговаяКомиссияСделки ПО (ТорговаяКомиссияСделки.Сделка = УсловияСделокРЕПО.СделкаРЕПО) И (УсловияСделокРЕПО.ЧастьСделкиРЕПО = 1) ЛЕВОЕ СОЕДИНЕНИЕ РегистрНакопления.РасходыПоСделке.Обороты( &НачалоПериода, &КонецПериода, , Организация = &Организация И ВидЗадолженности = ЗНАЧЕНИЕ(Справочник.ВидыЗадолженности.ПоБрокерскойКомиссии) И Сделка В (ВЫБРАТЬ РеквизитыСделок.СделкаРЕПО ИЗ РеквизитыСделок)) КАК БрокерскаяКомиссияСделки ПО (БрокерскаяКомиссияСделки.Сделка = УсловияСделокРЕПО.СделкаРЕПО) И (УсловияСделокРЕПО.ЧастьСделкиРЕПО = 1) ГДЕ ВЫБОР КОГДА УсловияСделокРЕПО.ЧастьСделкиРЕПО = 2 ТОГДА УсловияСделокРЕПО.ДатаВторойЧастиРЕПО МЕЖДУ &НачалоПериода И &КонецПериода ИНАЧЕ УсловияСделокРЕПО.СделкаРЕПО.Дата МЕЖДУ &НачалоПериода И &КонецПериода КОНЕЦ И УсловияСделокРЕПО.Отменено = ЛОЖЬ И ЕСТЬNULL(ТорговаяКомиссияСделки.Валюта, &ВалютаРубли) = &ВалютаРубли И ЕСТЬNULL(БрокерскаяКомиссияСделки.Валюта, &ВалютаРубли) = &ВалютаРубли {ГДЕ (УсловияСделокРЕПО.СчетДоверительногоУправления = &СчетДоверительногоУправления)}
ОБЪЕДИНИТЬ ВСЕ
ВЫБРАТЬ ИСТИНА, НеобработанныеСделки.СделкаРЕПО, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL ИЗ НеобработанныеСделки КАК НеобработанныеСделки
